#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>

int main()
{
    // Using C++ standard library container <vector> and algorithm <numeric>
    std::vector<double> measurements = {4.0, 9.0, 16.0};

    double sum = std::accumulate(measurements.begin(), measurements.end(), 0.0);
    double mean = sum / measurements.size();
    double rootMean = std::sqrt(mean); // from <cmath>

    std::cout << "Sum: " << sum << '\n';
    std::cout << "Square root of mean: " << rootMean << '\n';
}

#include <iostream>

// Inline function definition advises compiler to expand code at call sites
inline double cube(const double side)
{
    return side * side * side;
}

int main()
{
    const double values[] = {1.0, 2.5, 3.0};

    for (double side : values) {
        // cube(side) expands to (side * side * side) without function call jump
        std::cout << "Side: " << side << " -> Volume: " << cube(side) << '\n';
    }
}
